import java.util.Map;

// 준비 값: 페이지 크기(바이트)와 접근 목록이에요. "프로세스:가상 주소" 형식이에요.
static final int PAGE_SIZE = 16;
static final String ACCESSES = "A:5,B:5,A:18,A:20,B:20,A:37";

// 준비 코드: 프로세스마다 따로 가진 페이지 테이블이에요. 칸 번호가 페이지 번호, 값이 물리 프레임 번호예요.
// -1은 아직 연결되지 않은 페이지예요. 두 프로세스의 1번 페이지는 같은 프레임 2를 함께 써요(공유 페이지).
static final Map<String, int[]> TABLES = Map.of(
        "A", new int[]{5, 2, -1, 7},
        "B", new int[]{3, 2, 6, -1});

// 가상 주소를 물리 주소로 바꿔요. 연결된 프레임이 없으면 -1(페이지 폴트)을 돌려줘요.
static int translate(int[] table, int vaddr) {
    int page = vaddr / PAGE_SIZE;
    if (page >= table.length || table[page] < 0) return -1;
    int frame = table[page];
    // 고친 곳: 프레임의 시작 주소에 페이지 안의 위치(오프셋)를 더해요.
    // 오프셋은 가상 주소를 페이지 크기로 나눈 나머지예요. 페이지 크기가 바뀌어도 같은 식이에요.
    return frame * PAGE_SIZE + vaddr % PAGE_SIZE;
}

void main() {
    for (String access : ACCESSES.split(",")) {
        String[] parts = access.split(":");
        String process = parts[0];
        int vaddr = Integer.parseInt(parts[1]);
        int page = vaddr / PAGE_SIZE;
        int offset = vaddr % PAGE_SIZE;
        int paddr = translate(TABLES.get(process), vaddr);
        String result = paddr < 0 ? "폴트" : String.valueOf(paddr);
        System.out.println("프로세스 " + process + " | 가상 " + vaddr + " | 페이지 " + page + " | 오프셋 " + offset + " | 물리 " + result);
    }
}

